CREATE TABLE public.platform_request_notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), request_id uuid NOT NULL REFERENCES public.owner_requests(id) ON DELETE CASCADE, recipient_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), read_at timestamptz, UNIQUE(request_id, recipient_id));
GRANT SELECT ON public.platform_request_notifications TO authenticated;
GRANT UPDATE(read_at) ON public.platform_request_notifications TO authenticated;
GRANT ALL ON public.platform_request_notifications TO service_role;
ALTER TABLE public.platform_request_notifications ENABLE ROW LEVEL SECURITY;
CREATE POLICY platform_notifications_select ON public.platform_request_notifications FOR SELECT TO authenticated USING (recipient_id = auth.uid() AND public.is_super_admin());
CREATE POLICY platform_notifications_read ON public.platform_request_notifications FOR UPDATE TO authenticated USING (recipient_id = auth.uid() AND public.is_super_admin()) WITH CHECK (recipient_id = auth.uid() AND public.is_super_admin());
CREATE FUNCTION public.notify_platform_owner_request() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$ BEGIN INSERT INTO public.platform_request_notifications(request_id,recipient_id) SELECT NEW.id,user_id FROM public.user_roles WHERE role='super_admin' ON CONFLICT(request_id,recipient_id) DO NOTHING; RETURN NEW; END; $$;
REVOKE ALL ON FUNCTION public.notify_platform_owner_request() FROM PUBLIC;
CREATE TRIGGER platform_owner_request_notification AFTER INSERT ON public.owner_requests FOR EACH ROW EXECUTE FUNCTION public.notify_platform_owner_request();